<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Results'; require_role(['admin']); require_once __DIR__.'/../includes/header.php'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$term=(int)($_POST['term_id']??0);$subject=(int)($_POST['subject_id']??0);$st=$pdo->prepare('SELECT max_ca,max_exam FROM subjects WHERE id=? AND active=1');$st->execute([$subject]);$limits=$st->fetch();if(!$limits)throw new RuntimeException('Select a valid subject.');$pdo->beginTransaction();$save=$pdo->prepare("INSERT INTO results(student_id,subject_id,term_id,ca_score,exam_score,grade,remarks,entered_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE ca_score=VALUES(ca_score),exam_score=VALUES(exam_score),grade=VALUES(grade),remarks=VALUES(remarks),entered_by=VALUES(entered_by)");$items=$_POST['scores']??[];if(!empty($_FILES['scores_csv']['tmp_name']) && is_uploaded_file($_FILES['scores_csv']['tmp_name'])){$fh=fopen($_FILES['scores_csv']['tmp_name'],'r');if(!$fh)throw new RuntimeException('Could not read the CSV file.');$first=true;while(($line=fgetcsv($fh))!==false){if(count($line)<3)continue;if($first && strtolower(trim((string)$line[0]))==='registration_no'){$first=false;continue;}$first=false;$reg=trim((string)$line[0]);$ca=(float)$line[1];$exam=(float)$line[2];$find=$pdo->prepare("SELECT id FROM students WHERE admission_no=? AND class_id=? AND status='active'");$find->execute([$reg,(int)($_POST['class_id']??0)]);$sid=(int)$find->fetchColumn();if($sid)$items[$sid]=['ca'=>$ca,'exam'=>$exam];}fclose($fh);}foreach($items as $sid=>$score){$sid=(int)$sid;$ca=(float)($score['ca']??0);$exam=(float)($score['exam']??0);if($ca<0||$ca>(float)$limits['max_ca']||$exam<0||$exam>(float)$limits['max_exam'])throw new RuntimeException('One or more scores exceed the subject maximum.');[$g,$r]=grade($ca+$exam);$save->execute([$sid,$subject,$term,$ca,$exam,$g,$r,user()['id']]);}$pdo->commit();audit($pdo,'bulk_save','results',null,'Class result entry');flash('success','Class results saved.');redirect('results.php?class_id='.(int)($_POST['class_id']??0).'&term_id='.$term.'&subject_id='.$subject);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$classes=$pdo->query("SELECT * FROM classes WHERE active=1 ORDER BY FIELD(name,'JSS1','JSS2','JSS3','SSS1','SSS2','SSS3'),section")->fetchAll();$subjects=$pdo->query('SELECT * FROM subjects WHERE active=1 ORDER BY subject_name')->fetchAll();$terms=$pdo->query('SELECT * FROM academic_terms ORDER BY is_current DESC,id DESC')->fetchAll();$classId=(int)($_GET['class_id']??0);$termId=(int)($_GET['term_id']??($terms[0]['id']??0));$subjectId=(int)($_GET['subject_id']??($subjects[0]['id']??0));$students=[];if($classId){$st=$pdo->prepare("SELECT s.id,s.admission_no,s.surname,s.firstname,r.ca_score,r.exam_score,r.grade FROM students s LEFT JOIN results r ON r.student_id=s.id AND r.term_id=? AND r.subject_id=? WHERE s.class_id=? AND s.status='active' ORDER BY s.surname,s.firstname");$st->execute([$termId,$subjectId,$classId]);$students=$st->fetchAll();}$success=flash('success');
?><h2>Class Results & C/A Entry</h2><?php if($success):?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<div class="card p-3 mb-3"><form method="get" class="row g-2"><div class="col-md-4"><label>Class / Arm</label><select class="form-select" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $c):?><option value="<?=$c['id']?>" <?=$classId===(int)$c['id']?'selected':''?>><?=e($c['name'].$c['section'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Term</label><select class="form-select" name="term_id"><?php foreach($terms as $x):?><option value="<?=$x['id']?>" <?=$termId===(int)$x['id']?'selected':''?>><?=e($x['session_name'].' '.$x['term_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Subject</label><select class="form-select" name="subject_id"><?php foreach($subjects as $x):?><option value="<?=$x['id']?>" <?=$subjectId===(int)$x['id']?'selected':''?>><?=e($x['subject_name'])?></option><?php endforeach;?></select></div><div class="col-md-2 d-flex align-items-end"><button class="btn btn-primary w-100">Load class list</button></div></form></div>
<?php if($classId):?><form method="post" enctype="multipart/form-data" class="card p-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="class_id" value="<?=$classId?>"><input type="hidden" name="term_id" value="<?=$termId?>"><input type="hidden" name="subject_id" value="<?=$subjectId?>"><div class="d-flex justify-content-between"><h5>Enrolled students (<?=count($students)?>)</h5><span>Enter scores below or upload CSV</span></div><div class="alert alert-info">CSV format: <code>registration_no,ca,exam</code>. Upload only the selected class arm, subject and term.</div><div class="mb-3"><label>Upload class scores (CSV)</label><input class="form-control" type="file" name="scores_csv" accept=".csv,text/csv"></div><div class="table-responsive"><table class="table"><thead><tr><th>Registration No.</th><th>Student</th><th>CA (max 40)</th><th>Exam (max 60)</th><th>Grade</th></tr></thead><tbody><?php foreach($students as $s):?><tr><td><?=e($s['admission_no'])?></td><td><?=e($s['surname'].' '.$s['firstname'])?></td><td><input class="form-control" type="number" min="0" max="40" step=".01" name="scores[<?=$s['id']?>][ca]" value="<?=e((string)($s['ca_score']??0))?>" required></td><td><input class="form-control" type="number" min="0" max="60" step=".01" name="scores[<?=$s['id']?>][exam]" value="<?=e((string)($s['exam_score']??0))?>" required></td><td><?=e($s['grade']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php if($students):?><button class="btn btn-success">Save all class results</button><?php else:?><p>No active students are enrolled in this class arm.</p><?php endif;?></form><?php endif;?>
